  translate:'m4 5 7 0M7 3v2M3 10c4 0 7-3 7-5M4 6c0 3 3 6 6 7M12 20l5-12 5 12M14 16h6',
  code:'m8 6-6 6 6 6M16 6l6 6-6 6m-3-15-2 18',
  image:'M3 3h18v18H3ZM3 17l6-6 4 4 3-3 5 5M16 7h.01',
