  edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z',
  trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',
  globe:'M3 12h18M12 3c6 6 6 12 0 18-6-6-6-12 0-18M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
  spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',
  paste:'M9 4H5v17h14V4h-4M9 2h6v5H9ZM8 11h8M8 15h6',
  terminal:'m4 7 5 5-5 5M12 17h8', shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5ZM8 12l3 3 5-6',
