function fileReadHtml(tool){
 if(tool.name!=='read_file'||tool.status!=='succeeded')return '';
 try{const r=JSON.parse(tool.result);if(typeof r.text!=='string')return '';
 return `<div class="tool-file"><p>${escapeHtml(r.path||'')} · строки ${escapeHtml(String(r.start_line??''))}–${escapeHtml(String(r.end_line??''))}${r.has_more?' · есть продолжение':''}</p><button class="button" data-copy-tool-text>Копировать текст</button><pre>${escapeHtml(r.text)}</pre></div>`;}catch{return '';}
}
function toolHtml(tool,pending=false){
  const execution=executionHtml(tool),fileRead=fileReadHtml(tool);
  if(tool.name==='update_plan'&&tool.status==='succeeded')return planHtml(tool);
  const status=actionStatus(tool,pending),labels={running:'Выполняется',awaiting_approval:'Ожидает подтверждения',succeeded:'Выполнено',denied:'Отклонено',expired:'Время истекло',cancelled:'Прервано',failed:'Ошибка',skipped:'Пропущено',timed_out:'Лимит времени',needs_input:'Нужны данные',legacy:'Завершено · старый формат'};
  const marker=status==='running'?'<span class="spinner"></span>':status==='succeeded'?icon('check'):status==='awaiting_approval'?icon('shield'):['denied','failed','cancelled','expired','timed_out'].includes(status)?icon('close'):'<span aria-hidden="true">—</span>';
  return `<details class="tool-card tool-${escapeHtml(status)}" data-tool-status="${escapeHtml(status)}"><summary>${marker}<span>${escapeHtml(tool.name)}</span><span class="tool-status-label">${escapeHtml(labels[status]||status)}${escapeHtml(browserToolTiming(tool))}</span></summary><pre>${execution?escapeHtml(tool.arguments?.command||''):escapeHtml(JSON.stringify(tool.arguments,null,2))+(!fileRead&&tool.result!==undefined?'\n\n'+escapeHtml(tool.result):'')}</pre>${fileRead}${execution}${changeButton(tool)}</details>`;
}
function renderMessages(){const target=$('#conversation');if(!state.chat?.messages?.length&&!state.busy){target.className='';target.innerHTML=welcome();return;}target.className='conversation';target.innerHTML=(state.chat?.messages||[]).map((message,index)=>messageHtml(message,index)).join('')+(state.busy?streamHtml():'');enhanceMarkdown(target);if(!state.busy&&state.chat?.messages.at(-1)?.role==='user'){const actions=target.lastElementChild?.querySelector('.message-actions');if(actions){const retry=document.createElement('button');retry.className='icon-button';retry.dataset.action='retry';retry.title='Повторить запрос';retry.innerHTML=icon('refresh');actions.append(retry);}}followScroll();}
function diagnosticsHtml(d){
 if(!d)return '';const e=d.execution||{},hasFacts=Number(e.actions||0)>0;if(!hasFacts)return '';
 return `<details class="assistant-report"><summary>${hasFacts?'По инструментам: '+(e.succeeded||0)+' выполнено · '+(e.failed||0)+' ошибок · '+(e.stopped||0)+' остановлено':'Промпт и параметры ответа'}</summary>${hasFacts?`<p>Изменённых файлов с проверкой записи: ${(e.verified_changed_files||[]).length}. Команд: ${(e.commands||[]).length}. ${escapeHtml(e.note||'')}</p>${d.grounding_warning?'<p class="compute-fallback">Ответ модели всё ещё может противоречить результатам. Проверьте карточки инструментов.</p>':''}`:''}<pre>${escapeHtml(JSON.stringify(e,null,2))}</pre><details><summary>Диагностика модели${d.grounding_retry?' · ответ перепроверялся':''}</summary><pre>${escapeHtml(JSON.stringify(d,null,2))}</pre></details></details>`;
}
async function showAssistantConfig(){const box=$('#assistant-config-output');box.classList.remove('hidden');box.textContent='Чтение сохранённого промпта и метаданных Ollama…';try{const config=await api('/api/assistant/config');box.textContent=JSON.stringify(config,null,2);}catch(error){box.textContent=error.message;}}
function messageHtml(message,index){const user=message.role==='user';const time=new Date(message.created).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'});return `<article class="message ${user?'user':'assistant'}" data-message="${index}"><div class="message-head"><span class="avatar">${user?'ВЫ':'<img src="/logo.svg" alt="">'}</span><span>${user?'Вы':escapeHtml(message.model?modelName(message.model):'Gemma')}</span><span class="time">${time}</span></div>${responseTimingHtml(message)}${user?'':diagnosticsHtml(message.diagnostics)}${user?'':reasoningHtml(message.diagnostics?.thinking)}${message.attachments?.length?`<div class="message-attachments">${message.attachments.map(a=>attachmentHtml(a)).join('')}</div>`:''}${message.tools?.length?`<div class="tool-log">${toolsHtml(message.tools)}</div>`:''}<div class="message-body">${user?escapeHtml(message.content):markdown(message.content)}</div>${user?'':sourcesHtml(message.tools)}<div class="message-actions"><button class="icon-button" data-copy-message="${index}" title="Копировать">${icon('copy')}</button><button class="icon-button" data-save-message="${index}" title="Сохранить .md">${icon('download')}</button>${user?`<button class="icon-button" data-edit-message="${index}" title="Использовать как новый запрос">${icon('edit')}</button>`:index===state.chat.messages.length-1?`<button class="icon-button" data-action="retry" title="Перегенерировать">${icon('refresh')}</button>`:''}</div></article>`;}
function streamHtml(){return `<article class="message assistant" id="stream-message"><div class="message-head"><span class="avatar"><img src="/logo.svg" alt=""></span><span>${escapeHtml(modelName(state.settings[modelField()]))}</span><span class="time">сейчас</span></div><div class="response-timing response-timing-live" id="stream-duration" role="timer">Работаю · &lt; 1 с</div><details class="reasoning" id="stream-reasoning" hidden><summary>Рассуждения</summary><pre></pre></details><div class="tool-log" id="stream-tools">${toolsHtml(state.streamTools)}</div><div id="approvals">${state.approvals.map(approvalHtml).join('')}</div><div class="message-body" id="stream-body">${markdown(state.streamText)}<span class="cursor"></span></div><div class="typing" id="stream-notice"><span class="spinner"></span><span>${escapeHtml(state.notice||'Подготовка ответа…')}</span></div></article>`;}
function approvalHtml(approval){return `<div class="approval" data-approval-card="${approval.id}"><div class="approval-title">${icon('shield')}${escapeHtml(approval.title)}</div><pre>${escapeHtml(approval.details)}</pre><div class="approval-actions"><button class="button primary" data-approve="${approval.id}">Разрешить один раз</button><button class="button" data-deny="${approval.id}">Отклонить</button></div></div>`;}
let renderTimer;
function scheduleStream(){if(renderTimer)return;renderTimer=setTimeout(()=>{renderTimer=null;const body=$('#stream-body');if(!body)return;body.innerHTML=markdown(state.streamText)+'<span class="cursor"></span>';enhanceMarkdown(body);$('#stream-tools').innerHTML=toolsHtml(state.streamTools);const reason=$('#stream-reasoning');if(reason){reason.hidden=!state.streamThinking;reason.querySelector('pre').textContent=state.streamThinking||'';}$('#approvals').innerHTML=state.approvals.map(approvalHtml).join('');$('#stream-notice span:last-child').textContent=state.notice||'Готовим ответ…';followScroll();},70);}
function followScroll(force=false){if(state.scrollFollow||force){const scroll=$('#scroll');scroll.scrollTop=scroll.scrollHeight;}}
function updateSend(){if(typeof refreshToolControls==='function')refreshToolControls();$('#model-name').disabled=state.busy||modelMenuSaving;if(state.busy)closeModelMenu();const send=$('#send');send.classList.toggle('stop',state.busy);send.innerHTML=icon(state.busy?'stop':'arrow');send.setAttribute('aria-label',state.busy?'Остановить ответ':'Отправить');send.disabled=!state.busy&&(!$('#prompt').value.trim()&&!state.pending.length||state.uploading>0);}
function resizeInput(){const prompt=$('#prompt');prompt.style.height='auto';prompt.style.height=Math.min(220,prompt.scrollHeight)+'px';updateSend();localStorage.setItem('gemma.draft',prompt.value);}
async function refreshChats(){state.chats=await api('/api/chats');renderChats();}
async function selectChat(id){if(state.busy){toast('Сначала остановите текущий ответ.');return;}state.chat=await api('/api/chats/'+id);localStorage.setItem('gemma.lastChat',id);setMode(modes[state.chat.mode]?state.chat.mode:'agent');$('#chat-title').textContent=state.chat.title;renderChats();renderMessages();followScroll(true);if(innerWidth<761)document.body.classList.add('sidebar-hidden');}
function newChat(){if(state.busy){toast('Сначала остановите текущий ответ.');return;}state.chat=null;localStorage.removeItem('gemma.lastChat');state.pending=[];$('#chat-title').textContent='Новый чат';$('#prompt').value='';renderChats();renderMessages();renderPending();resizeInput();$('#prompt').focus();}
async function send(retry=false){
  if(state.busy)return stopRun();if(state.uploading)return;
  let content=$('#prompt').value.trim();let attachments=[...state.pending];
  if(retry){const previous=[...(state.chat?.messages||[])].reverse().find(m=>m.role==='user');if(!previous)return;content=previous.content;attachments=previous.attachments||[];}
  if(!content&&!attachments.length)return;
  if(!state.chat)state.chat=await api('/api/chats',{method:'POST',body:{mode:state.mode}});
  localStorage.setItem('gemma.lastChat',state.chat.id);const payload={conversation:state.chat.id,content,attachments:attachments.map(a=>a.id),mode:state.mode,source:$('#source').value,target:$('#target').value,retry,thinking:thinkingChoice,web:webChoice,security_test:!!document.getElementById("security-test")?.checked};
  if(retry){if(state.chat.messages.at(-1)?.role==='assistant')state.chat.messages.pop();if(state.chat.messages.at(-1)?.role==='user')state.chat.messages.pop();}
  state.chat.messages.push({role:'user',content,attachments,tools:[],created:new Date().toISOString()});
  state.busy=true;state.run=null;state.streamText='';state.streamThinking='';state.streamTools=[];state.approvals=[];state.notice='Подготовка ответа…';state.scrollFollow=true;state.pending=[];$('#prompt').value='';resizeInput();renderPending();renderMessages();startResponseTimer();
  try{await consumeEvents('/api/chat',payload,async event=>{
    switch(event.type){case 'start':state.run=event.run_id;break;
      case 'replace_content':state.streamText=event.text;state.notice='';scheduleStream();break;
      case 'thinking':state.streamThinking=(state.streamThinking||'')+event.text;state.notice='Рассуждение…';scheduleStream();break;
      case 'token':state.streamText+=event.text;state.notice='Генерация ответа…';scheduleStream();break;
      case 'notice':state.notice=event.message;scheduleStream();break;
      case 'progress':state.notice=event.message||'Обработка документа…';scheduleStream();break;
      case 'extracted':state.streamTools.push({name:'Распознано: '+event.name,arguments:{file:event.name},result:event.text,status:'succeeded'});scheduleStream();break;
      case 'tool_start':state.streamTools.push({id:event.id,name:event.name,arguments:event.arguments,status:event.status||'running'});state.notice='Выполняется '+event.name;scheduleStream();break;
      case 'tool_result':{const tool=[...state.streamTools].reverse().find(t=>event.tool.id?t.id===event.tool.id:t.name===event.tool.name&&t.result===undefined);if(tool)Object.assign(tool,event.tool);else state.streamTools.push(event.tool);state.notice=event.tool.status==='succeeded'?'Обработка результата…':event.tool.status==='denied'?'Действие отклонено':event.tool.status==='failed'?'Ошибка действия':'Завершение действия…';scheduleStream();break;}
      case 'approval':{const tool=state.streamTools.find(t=>t.id===event.tool_id);if(tool)tool.status='awaiting_approval';}state.approvals.push(event);toast('Агент ожидает вашего подтверждения.');state.notice='Ожидается ваше подтверждение';scheduleStream();break;
      case 'approval_closed':{const tool=state.streamTools.find(t=>t.id===event.tool_id);if(tool)tool.status=event.status||(event.allowed?'running':'denied');}state.approvals=state.approvals.filter(a=>a.id!==event.id);state.notice=event.allowed?'Выполняется действие…':'Действие не выполняется';scheduleStream();break;
      case 'saved':state.chat=event.conversation;$('#chat-title').textContent=state.chat.title;break;
      case 'error':toast(event.message,true);break;
    }
  });}catch(error){toast(error.message,true);}
  finally{stopResponseTimer();state.busy=false;state.run=null;state.approvals=[];clearTimeout(renderTimer);renderTimer=null;try{state.chat=await api('/api/chats/'+payload.conversation);}catch{}renderMessages();await refreshChats();updateSend();}
}
async function stopRun(){if(state.run){await api('/api/stop/'+state.run,{method:'POST',body:{}});state.notice='Остановка…';scheduleStream();}}
async function uploadFiles(files){const available=12-state.pending.length;if(files.length>available)toast('В одном сообщении можно прикрепить до 12 файлов.');for(const file of Array.from(files).slice(0,available)){if(file.size>80*1024*1024){toast(file.name+': больше 80 МБ',true);continue;}state.uploading++;renderPending();try{const form=new FormData();form.append('file',file,file.name);const attachment=await api('/api/upload',{method:'POST',body:form});state.pending.push(attachment);}catch(error){toast(error.message,true);}finally{state.uploading--;renderPending();}}$('#prompt').focus();}
async function pasteNative(){const result=await api('/api/clipboard',{method:'POST',body:{}});if(result.text)insertText(result.text);if(result.attachments?.length){state.pending.push(...result.attachments.slice(0,12-state.pending.length));renderPending();}if(!result.text&&!result.attachments?.length)toast('Буфер пуст или формат не поддерживается.');}
async function pasteClipboard(){try{if(!navigator.clipboard?.read){const text=await navigator.clipboard.readText();insertText(text);return;}const items=await navigator.clipboard.read();let pasted=false;for(const item of items){const image=item.types.find(t=>t.startsWith('image/'));if(image){const blob=await item.getType(image);await uploadFiles([new File([blob],'clipboard-'+Date.now()+'.'+image.split('/')[1],{type:image})]);pasted=true;}else if(item.types.includes('text/plain')){insertText(await(await item.getType('text/plain')).text());pasted=true;}}if(!pasted)await pasteNative();}catch{try{await pasteNative();}catch{toast('Нажмите Ctrl / ⌘ + V в поле сообщения. Для файлов используйте перетаскивание.');$('#prompt').focus();}}}
function insertText(text){const prompt=$('#prompt');prompt.focus();const start=prompt.selectionStart,end=prompt.selectionEnd;prompt.setRangeText(text,start,end,'end');resizeInput();}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Скопировано');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove();toast('Скопировано');}}
function download(text,name,type='text/markdown;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportChat(){if(!state.chat){toast('Сначала начните диалог.');return;}const text='# '+state.chat.title+'\n\n'+state.chat.messages.map(message=>'## '+(message.role==='user'?'Вы':modelName(message.model)||'Gemma')+'\n\n'+message.content+(message.attachments?.length?'\n\nВложения: '+message.attachments.map(a=>a.name).join(', '):'')+(message.tools?.length?'\n\n'+message.tools.map(t=>'<details>\n<summary>'+t.name+'</summary>\n\n```text\n'+t.result+'\n```\n</details>').join('\n\n'):'')).join('\n\n---\n\n');download(text,(state.chat.title.replace(/[<>:"/\\|?*]/g,'').slice(0,65)||'chat')+'.md');}
function modelField(mode=state.mode){return mode==='translate'?'translation_model':mode==='agent'?'agent_model':'chat_model';}
function modelName(id){return state.catalog.find(m=>m.id===id)?.name||id||'Локальная модель';}
function hasModel(id){if(id==="whisper-small")return !!state.status?.speech_ready;return (state.status?.models||[]).some(m=>m.name===id||m.model===id);}
function modelOptions(role,selected,inherit=false){return (inherit?'<option value="">Как перевод в чате</option>':'')+state.catalog.filter(m=>m.role===role).map(m=>`<option value="${escapeHtml(m.id)}" ${m.id===selected?'selected':''}>${escapeHtml(m.name)}${state.status&&!hasModel(m.id)?' · скачать':''}</option>`).join('');}
let computeInfo=null,computeInstalling=false;
const computeMemory=bytes=>Number(bytes)>0?(Number(bytes)/1073741824).toFixed(1)+' ГБ':'—';
function computeSelection(){const value=$('#compute-device').value,colon=value.indexOf(':');return {backend:colon<0?value:value.slice(0,colon),device:colon<0?'':value.slice(colon+1),cpu_threads:Number($('#compute-threads').value),fallback_to_cpu:$('#compute-fallback').checked};}
function renderComputeRuntime(runtime){
 const element=$('#compute-runtime');if(!element||!runtime)return;
 const names={auto:'Автоматически',cpu:'Процессор',cuda:'NVIDIA CUDA',rocm:'AMD ROCm',vulkan:'Vulkan',metal:'Apple Metal'};
 const models=Array.isArray(runtime.loaded_models)?runtime.loaded_models:[];
 element.innerHTML=`<strong>Сохранено: ${escapeHtml(names[runtime.requested?.backend]||runtime.requested?.backend||'—')}</strong>${runtime.fallback_error?`<p class="compute-fallback">Запуск на CPU после ошибки ускорителя.<br>${escapeHtml(runtime.fallback_error)}</p>`:''}${models.length?models.map(m=>`<p>${escapeHtml(modelName(m.name||m.model))}<br>${typeof m.size_vram==='number'?(m.size_vram>0?'Память GPU: '+computeMemory(m.size_vram)+' · размер размещения: '+computeMemory(m.size):'Модель размещена на CPU'):'Движок не сообщил размещение модели'}</p>`).join(''):'<p>Сейчас модель не загружена. Фактическое размещение появится после запроса.</p>'}${runtime.installing?'<p>Устанавливаются компоненты движка…</p>':''}`;
}
async function loadCompute(refresh=false){
 const before=$('#compute-device').value||'auto';document.querySelectorAll('[data-action="save-settings"]').forEach(b=>b.disabled=true);
 try{computeInfo=await api(refresh?'/api/compute/refresh':'/api/compute',refresh?{method:'POST',body:{}}:{});
 const h=computeInfo.hardware||{},devices=h.devices||[],config=state.settings.compute||{backend:state.settings.cpu_only?'cpu':'auto',device:''};
 $('#compute-hardware').textContent=(h.cpu_name||h.architecture||'CPU').trim()+' · логических процессоров: '+(h.logical_cpus||1);
 $('#compute-threads').max=h.logical_cpus||512;
 const options=[{value:'auto',name:'Автоматически · GPU / CPU'},{value:'cpu',name:'Процессор · CPU'}];
 for(const d of devices){if(d.device_type===4)continue;options.push({value:d.backend+(d.device?':'+d.device:''),name:d.name+' · '+({vulkan:'Vulkan',cuda:'CUDA',metal:'Metal'}[d.backend]||d.backend)+(d.memory_bytes?' · '+computeMemory(d.memory_bytes):'')+(!computeInfo.packages[d.backend]?' · нужен модуль':'')});}
 const amd=devices.some(d=>d.vendor==='AMD')||(h.display_adapters||[]).some(d=>String(d.AdapterCompatibility).includes('Advanced Micro Devices'));
 if(amd)options.push({value:'rocm',name:'AMD ROCm · автоматический выбор совместимой карты'+(!computeInfo.packages.rocm?' · нужен модуль':'')});
 const selected=refresh?before:config.backend+(config.device?':'+config.device:'');
 if(!options.some(o=>o.value===selected))options.push({value:selected,name:selected+' · устройство не обнаружено'});
 $('#compute-device').innerHTML=options.map(o=>`<option value="${escapeHtml(o.value)}">${escapeHtml(o.name)}</option>`).join('');$('#compute-device').value=selected;
 renderComputeRuntime(computeInfo.runtime);
 $('#compute-packages').innerHTML=computeInfo.package_install_supported?[['vulkan','Vulkan · NVIDIA / AMD / Intel','около 40 МБ',devices.some(d=>d.backend==='vulkan')],['cuda','CUDA · NVIDIA','около 2 ГБ',devices.some(d=>d.backend==='cuda')],['rocm','ROCm · AMD','около 1 ГБ',amd]].map(([backend,name,size,found])=>`<div class="compute-package"><div><strong>${name}</strong><span>${computeInfo.packages[backend]?'Модуль установлен':found?'Компоненты отдельно · '+size:'Подходящее устройство не обнаружено'}</span></div>${!computeInfo.packages[backend]?`<button class="button" data-install-compute="${backend}" ${!found||computeInstalling?'disabled':''}>Скачать модуль</button>`:'<span class="installed-mark">Готово</span>'}</div>`).join(''):'<p class="form-help">На этой платформе библиотеки GPU поставляются вместе с Ollama.</p>';
 }catch(error){$('#compute-hardware').textContent='Не удалось получить список устройств: '+error.message;}finally{document.querySelectorAll('[data-action="save-settings"]').forEach(b=>b.disabled=computeInstalling);}
}
async function installCompute(backend){
 if(computeInstalling||state.busy||state.downloading){toast('Дождитесь окончания текущей операции.');return;}
 computeInstalling=true;state.downloading=true;const progress=$('#compute-progress');progress.textContent='Подготовка модуля…';document.querySelectorAll('[data-install-compute],[data-action="save-settings"]').forEach(b=>b.disabled=true);
 try{await consumeEvents('/api/compute/install',{backend},event=>{if(event.type==='progress')progress.textContent=event.message;if(event.type==='error')throw new Error(event.message);});toast('Модуль готов. Выберите устройство и сохраните настройки.');}
 catch(error){progress.textContent='Не удалось установить: '+error.message;toast(error.message,true);}
 finally{computeInstalling=false;state.downloading=false;document.querySelectorAll('[data-action="save-settings"]').forEach(b=>b.disabled=false);await loadCompute(true);await refreshStatus();}
}
async function retryCompute(){if(state.busy||computeInstalling){toast('Дождитесь окончания текущей операции.');return;}$('#compute-progress').textContent='Повторная подготовка сохранённого устройства…';try{computeInfo=await api('/api/compute/retry',{method:'POST',body:{}});renderComputeRuntime(computeInfo.runtime);$('#compute-progress').textContent=computeInfo.runtime?.fallback_error?'Ускоритель снова не запустился. Сохранён резервный режим CPU.':'Сохранённое устройство подготовлено. Следующий запрос загрузит модель.';}catch(error){$('#compute-progress').textContent=error.message;}}
function renderSettingsModels(){for(const [field,id,role] of [['translation_model','translation-model-setting','translate'],['quick_model','quick-model-setting','translate'],['agent_model','agent-model-setting','assistant'],['chat_model','chat-model-setting','assistant']]){$('#'+id).innerHTML=modelOptions(role,state.settings[field],field==='quick_model');$('#'+id).value=state.settings[field]||'';}}
async function refreshStatus(){try{state.status=await api('/api/status');if($('#settings-dialog')?.open)renderComputeRuntime(state.status.compute);const needed=[state.settings.translation_model,state.settings.agent_model,state.settings.chat_model,state.settings.quick_model].filter(Boolean);const ready=state.status.online&&needed.every(hasModel);$('#system-dot').classList.toggle('off',!ready);$('#system-label').textContent=ready?'Система готова':state.status.online?'Нужно скачать выбранные модели':'Ollama недоступна';$('#models-status').innerHTML=renderModelCatalog();renderActiveModel();}catch{$('#system-label').textContent='Нет связи с сервером';}}
async function showSettings(){const fresh=await api('/api/bootstrap');state.settings=fresh.settings;renderSettingsModels();$('#search-provider').value=state.settings.web?.provider||'duckduckgo';$('#searxng-url').value=state.settings.web?.searxng_url||'';$('#brave-key').value=state.settings.web?.brave_key||'';$('#browser-visible').checked=!!state.settings.web?.browser_visible;$('#reranker-enabled').checked=state.settings.web?.reranker_enabled!==false;$('#reranker-help').textContent=rerankerHelpText;const a=state.settings.assistant||{};$('#agent-instructions').value=a.agent_instructions||'';$('#chat-instructions').value=a.chat_instructions||'';$('#agent-temperature').value=a.agent_temperature??0.1;$('#chat-temperature').value=a.chat_temperature??0.7;$('#repeat-penalty').value=a.repeat_penalty??1.05;$('#assistant-config-output').classList.add('hidden');$('#workspace-setting').value=state.settings.workspace;$('#theme-setting').value=state.settings.theme;$('#agent-actions-setting').value=state.settings.agent_max_actions||12;$('#agent-timeout-setting').value=Math.round((state.settings.agent_timeout_seconds||900)/60);$('#compute-threads').value=state.settings.compute?.cpu_threads||0;$('#compute-fallback').checked=state.settings.compute?.fallback_to_cpu!==false;$('#compute-progress').textContent='';$('#settings-dialog').showModal();$('#computer-access-setting').checked=state.settings.computer_access!==false;$('#quick-source-setting').value=state.settings.quick_source||'auto';$('#quick-target-setting').value=state.settings.target;$('#quick-hotkey-setting').value=state.settings.quick_hotkey||'Control+Shift+T';$('#quick-area-hotkey-setting').value=state.settings.quick_area_hotkey||'Control+Shift+O';$('#voice-duration').value=localStorage.getItem('gemma.voiceDuration')||'10';await loadCompute();await refreshStatus();const hotkey=state.status?.hotkey;if(hotkey?.area_hotkey)$('#area-hotkey-state').textContent=hotkey.area_ready?'Область экрана: '+hotkey.area_hotkey+' · Esc — отмена. На Mac нужна запись экрана.':'Сочетание области недоступно: '+(hotkey.area_error||'не зарегистрировано');if(hotkey){$('#hotkey-state').textContent=hotkey.ready?'Сочетание зарегистрировано: '+hotkey.hotkey+'. Studio должна оставаться запущенной. На macOS нужен «Универсальный доступ».':'Не удалось зарегистрировать сочетание: '+(hotkey.error||'занято другим приложением')+'. Выберите другое сочетание.';}}
async function saveSettings(){const fresh=await api('/api/bootstrap');const value={...fresh.settings,assistant:{agent_instructions:$('#agent-instructions').value,chat_instructions:$('#chat-instructions').value,agent_temperature:Number($('#agent-temperature').value),chat_temperature:Number($('#chat-temperature').value),repeat_penalty:Number($('#repeat-penalty').value)},web:{provider:$('#search-provider').value,searxng_url:$('#searxng-url').value.trim(),brave_key:$('#brave-key').value.trim(),browser_visible:$('#browser-visible').checked,reranker_enabled:$('#reranker-enabled').checked},agent_max_actions:Number($('#agent-actions-setting').value),agent_timeout_seconds:Number($('#agent-timeout-setting').value)*60,translation_model:$('#translation-model-setting').value,quick_model:$('#quick-model-setting').value,agent_model:$('#agent-model-setting').value,chat_model:$('#chat-model-setting').value,workspace:$('#workspace-setting').value,theme:$('#theme-setting').value,compute:computeSelection(),cpu_only:computeSelection().backend==='cpu',computer_access:$('#computer-access-setting').checked,quick_source:$('#quick-source-setting').value,quick_hotkey:$('#quick-hotkey-setting').value.trim(),quick_area_hotkey:$('#quick-area-hotkey-setting').value.trim(),source:$('#source').value,target:$('#quick-target-setting').value};state.settings=await api('/api/settings',{method:'POST',body:value});localStorage.setItem('gemma.voiceDuration',$('#voice-duration').value);setTheme();$('#target').value=state.settings.target;updateWorkspace();$('#settings-dialog').close();renderActiveModel();await refreshStatus();toast('Настройки сохранены. Выбранное устройство применяется к следующим запросам.');if($('#file-panel').classList.contains('visible'))await refreshTree();}
function updateWorkspace(){$('#workspace-label').textContent=state.settings.workspace;$('#workspace-label').title=state.settings.workspace;$('#file-panel-path').textContent=state.settings.workspace;}
async function toggleFiles(){$('#file-panel').classList.toggle('visible');if($('#file-panel').classList.contains('visible'))await refreshTree();}
async function refreshTree(){$('#file-tree').innerHTML='<p class="empty-list">Читаем файлы…</p>';try{const items=await api('/api/tree');$('#file-tree').innerHTML=items.length?items.map(item=>`<button class="tree-item" style="padding-left:${8+item.depth*11}px" data-tree-path="${escapeHtml(item.path)}" title="${escapeHtml(item.path)}">${icon(item.directory?'folder':'file')}<span>${escapeHtml(item.name)}</span></button>`).join(''):'<p class="empty-list">Папка пока пуста.<br>Выберите папку проекта в настройках.</p>';}catch(error){$('#file-tree').textContent=error.message;}}
const documentState={item:null,read:null,run:null,busy:false,reading:false,output:null,session:0};
function documentOptions(){const source=$('#document-source').value;return {attachment:documentState.item.id,start_page:Number($('#document-start').value),max_pages:Number($('#document-count').value),ocr:$('#document-ocr').checked,source,target:$('#document-target').value,language:source==='auto'?'en-US':source==='en'?'en-US':source};}
function documentControls(){const busy=documentState.busy||documentState.reading;$('#document-dialog').querySelectorAll('input,select,[data-action="read-document"],[data-action="insert-document"]').forEach(b=>b.disabled=busy);$('#document-translate').disabled=busy;$('#document-stop').disabled=!documentState.run;$('#document-next').disabled=busy||!documentState.read?.has_more;}
async function openDocument(item){if(documentState.busy||documentState.reading){toast('Дождитесь обработки документа.');return;}Object.assign(documentState,{item,read:null,run:null,output:null});documentState.session++;$('#document-title').textContent=item.name;const pdf=item.name.toLowerCase().endsWith('.pdf');$('#document-pages').classList.toggle('hidden',!pdf);$('#document-ocr-row').classList.toggle('hidden',!pdf);$('#document-next').classList.toggle('hidden',!pdf);$('#document-start').value=1;$('#document-count').value=5;$('#document-ocr').checked=false;$('#document-source').value=state.settings.source||'en';$('#document-target').value=state.settings.target||'ru';$('#document-result').classList.add('hidden');$('#document-text').textContent='';$('#document-progress').textContent='';$('#document-warnings').textContent='';$('#document-information').textContent='';$('#document-model').textContent='Переводчик: '+modelName(state.settings.translation_model)+'. '+(pdf?'Выгрузка выбранных страниц в Markdown.':'Перевод абзацами в DOCX: до 300 абзацев / 40000 символов; до 4000 символов в одном абзаце.');$('#document-translate').textContent=pdf?'Перевести выбранные страницы':'Перевести DOCX';$('#document-dialog').showModal();await readDocument();}
async function readDocument(){if(documentState.busy||documentState.reading)return;documentState.reading=true;const session=documentState.session;documentState.run=crypto.randomUUID();const readJob=documentState.run;$('#document-progress').textContent='Чтение документа…';documentControls();try{const result=await api('/api/documents/read',{method:'POST',body:{...documentOptions(),job:readJob}});if(session!==documentState.session)return;documentState.read=result;$('#document-text').textContent=result.text||'';$('#document-information').textContent=result.format==='pdf'?`Страницы ${result.start_page}–${result.end_page} из ${result.total_pages}${result.has_more?' · есть продолжение':''}`:`Абзацев: ${result.paragraphs_count??result.units_count} · текстовых участков: ${result.units_count}${result.complete?'':' · чтение сокращено'}`;$('#document-warnings').textContent=(result.warnings||[]).join(' ');$('#document-progress').textContent='Текст извлечён локально.';}catch(error){if(session===documentState.session)$('#document-progress').textContent=error.message;}finally{documentState.reading=false;if(documentState.run===readJob)documentState.run=null;documentControls();}}
async function translateDocument(){if(documentState.busy||documentState.reading||state.busy||state.downloading){toast('Дождитесь текущей операции.');return;}documentState.busy=true;documentState.output=null;const session=documentState.session;$('#document-result').classList.add('hidden');$('#document-progress').textContent='Подготовка перевода…';documentControls();try{await consumeEvents('/api/documents/translate',documentOptions(),event=>{if(session!==documentState.session)return;if(event.type==='start'){documentState.run=event.run_id;documentControls();}if(event.type==='progress')$('#document-progress').textContent=event.message+(event.total?` · ${event.completed}/${event.total}`:'');if(event.type==='error')throw new Error(event.message);if(event.type==='document_result'){documentState.output=event.attachment;$('#document-download').href='/api/files/'+event.attachment.id;$('#document-download').download=event.attachment.name;$('#document-report').textContent=`Обработано ${event.report.unit_kind==='paragraph'?'абзацев':'страниц'}: ${event.report.processed_units||0}. Переведено моделью: ${event.report.translated_units||0}. Запросов перевода: ${event.report.inference_calls??event.report.translated_units??0}${event.report.format_retries?` (повторов форматирования: ${event.report.format_retries})`:''}. `+(event.report.warnings||[]).join(' ');$('#document-result').classList.remove('hidden');$('#document-result').scrollIntoView({block:'nearest'});}});}catch(error){if(session===documentState.session)$('#document-progress').textContent=error.message;}finally{documentState.busy=false;documentState.run=null;documentControls();}}
async function stopDocument(){if(documentState.run){await api('/api/stop/'+documentState.run,{method:'POST',body:{}});$('#document-progress').textContent='Останавливаем перевод…';}}
async function closeDocument(){await stopDocument();documentState.session++;$('#document-dialog').close();}
async function preview(id){const attachment=[...state.pending,...(state.chat?.messages||[]).flatMap(m=>m.attachments||[])].find(a=>a.id===id);if(!attachment)return;if(attachment.kind==='document'){await openDocument(attachment);return;}$('#preview-title').textContent=attachment.name;const body=$('#preview-body');body.replaceChildren();if(attachment.kind==='image'){const image=document.createElement('img');image.className='preview-img';image.src='/api/files/'+id;image.alt=attachment.name;body.append(image);}else if(attachment.kind==='audio'){const audio=document.createElement('audio');audio.controls=true;audio.src='/api/files/'+id;audio.style.width='100%';body.append(audio);}else if(attachment.kind==='text'){const text=await(await fetch('/api/files/'+id)).text();const content=document.createElement('div');content.className='message-body';content.innerHTML=markdown(text);body.append(content);enhanceMarkdown(content);}else{const p=document.createElement('p');p.textContent='Предпросмотр этого формата не поддерживается.';body.append(p);}const link=document.createElement('a');link.href='/api/files/'+id;link.download=attachment.name;link.textContent='Скачать файл';link.className='button';link.style.marginTop='18px';body.append(link);$('#preview-dialog').showModal();}
function editDialog(title,value,confirmLabel,callback){$('#edit-title').textContent=title;$('#edit-value').value=value;$('#edit-confirm').textContent=confirmLabel;$('#edit-confirm').onclick=async()=>{try{await callback($('#edit-value').value);$('#edit-dialog').close();}catch(error){toast(error.message,true);}};$('#edit-dialog').showModal();$('#edit-value').focus();}
function chatMenu(id,button){document.querySelector('.context-menu')?.remove();const menu=document.createElement('div');menu.className='context-menu';const rect=button.getBoundingClientRect();menu.style.left=Math.min(rect.left,innerWidth-200)+'px';menu.style.top=Math.min(rect.bottom,innerHeight-120)+'px';menu.innerHTML=`<button data-rename-chat="${id}">${icon('edit')}Переименовать</button><button class="danger" data-delete-chat="${id}">${icon('trash')}Удалить чат</button>`;document.body.append(menu);}
async function pullModels(model=null){if(state.downloading)return;state.downloading=true;const progress=$('#pull-progress');progress.textContent='Подключение к Ollama…';document.querySelectorAll('[data-download-model],[data-action="pull"]').forEach(b=>b.disabled=true);let failed=false;try{await consumeEvents('/api/models/pull',model?{model,directory:modelDirectories.get(model)||state.status?.model_locations?.[model]||''}:{},event=>{if(event.type==='progress'){const item=event.progress;progress.textContent=modelName(event.model)+'\n'+item.status+(item.total?' · '+Math.floor(100*(item.completed||0)/item.total)+'%':'');}if(event.type==='error'){failed=true;throw new Error(event.message);}});if(!failed)progress.textContent='Скачивание завершено. Модель можно выбрать для нужной задачи.';}catch(error){progress.textContent='Не удалось скачать: '+error.message;}finally{state.downloading=false;await refreshStatus();document.querySelectorAll('[data-action="pull"]').forEach(b=>b.disabled=false);}}


function openVoice(){if(state.voice){toast('Запись уже идёт.');return;}$('#voice-result').classList.add('hidden');$('#use-voice').classList.add('hidden');$('#voice-state').textContent='Продиктуйте сообщение';$('#voice-time').textContent='00:00';$('#record-button').innerHTML=icon('mic')+'Начать запись';$('#record-button').disabled=false;$('#system-record-button').disabled=false;$('#voice-dialog').showModal();}
function timerVoice(){const started=Date.now();$('#voice-orb').classList.add('recording');return setInterval(()=>{const seconds=Math.floor((Date.now()-started)/1000);$('#voice-time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');},300);}
function voiceResult(text){$('#voice-result').value=text;$('#voice-result').classList.remove('hidden');$('#use-voice').classList.toggle('hidden',!text);$('#voice-state').textContent=text?'Речь распознана. Проверьте текст.':'Речь не обнаружена';}
async function startRecord(){let openedStream;if(state.voice){if(state.voice.recorder?.state==='recording')state.voice.recorder.stop();else if(state.voice.job)await api('/api/stop/'+state.voice.job,{method:'POST',body:{}});return;}
  try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Запись в этом окне недоступна. Используйте «Системный микрофон».');const stream=await navigator.mediaDevices.getUserMedia({audio:true});openedStream=stream;const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(type=>MediaRecorder.isTypeSupported(type));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});const voice={recorder,stream,chunks:[],timer:timerVoice()};state.voice=voice;
    recorder.ondataavailable=event=>{if(event.data.size)voice.chunks.push(event.data);};recorder.onstop=async()=>{clearInterval(voice.timer);clearTimeout(voice.timeout);stream.getTracks().forEach(track=>track.stop());$('#voice-orb').classList.remove('recording');if(voice.discard){state.voice=null;$('#record-button').disabled=false;$('#system-record-button').disabled=false;return;}$('#voice-state').textContent='Распознаём запись…';$('#record-button').disabled=true;try{const blob=new Blob(voice.chunks,{type:recorder.mimeType});const form=new FormData();form.append('file',new File([blob],'voice-'+Date.now()+(recorder.mimeType.includes('mp4')?'.m4a':'.webm'),{type:blob.type}));const attachment=await api('/api/upload',{method:'POST',body:form});const result=await api('/api/media',{method:'POST',body:{action:'audio',attachment:attachment.id}});voiceResult(result.text||'');}catch(error){toast(error.message,true);$('#voice-state').textContent='Не удалось распознать запись';}finally{state.voice=null;$('#record-button').disabled=false;$('#record-button').innerHTML=icon('mic')+'Записать ещё';$('#system-record-button').disabled=false;}};
    recorder.start();voice.timeout=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},120000);$('#voice-state').textContent='Запись идёт. Нажмите «Остановить», когда закончите.';$('#record-button').innerHTML=icon('stop')+'Остановить';$('#system-record-button').disabled=true;
  }catch(error){openedStream?.getTracks().forEach(track=>track.stop());toast(error.message,true);}}
async function systemRecord(){if(state.voice)return;const seconds=Number(localStorage.getItem('gemma.voiceDuration')||10);const job=crypto.randomUUID();const voice={job,timer:timerVoice()};state.voice=voice;$('#voice-state').textContent=`Системная запись · до ${seconds} секунд`;$('#record-button').innerHTML=icon('stop')+'Остановить';$('#system-record-button').disabled=true;try{const result=await api('/api/media',{method:'POST',body:{action:'record',seconds,job}});voiceResult(result.text||'');}catch(error){toast(error.message,true);$('#voice-state').textContent='Запись завершена';}finally{clearInterval(voice.timer);state.voice=null;$('#voice-orb').classList.remove('recording');$('#record-button').innerHTML=icon('mic')+'Начать запись';$('#system-record-button').disabled=false;}}
async function closeVoice(){if(state.voice?.recorder?.state==='recording'){state.voice.discard=true;state.voice.recorder.stop();}if(state.voice?.job)await api('/api/stop/'+state.voice.job,{method:'POST',body:{}});$('#voice-dialog').close();}

function bindEvents(){
  bindModelMenu();
  $('#prompt').addEventListener('input',resizeInput);$('#prompt').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send().catch(e=>toast(e.message,true));}});
  document.addEventListener('paste',event=>{if(document.querySelector('dialog[open]'))return;const files=Array.from(event.clipboardData?.items||[]).filter(item=>item.kind==='file').map(item=>item.getAsFile()).filter(Boolean);if(files.length){event.preventDefault();uploadFiles(files);}else if(!event.clipboardData?.getData('text/plain')&&event.target===$('#prompt')){event.preventDefault();pasteNative().catch(e=>toast(e.message,true));}});
  $('#file-input').addEventListener('change',event=>{uploadFiles(event.target.files);event.target.value='';});$('#chat-search').addEventListener('input',renderChats);
  $('#scroll').addEventListener('scroll',()=>{const scroll=$('#scroll');state.scrollFollow=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<140;});
  let dragCounter=0;document.addEventListener('dragenter',event=>{if(event.dataTransfer?.types?.includes('Files')){event.preventDefault();dragCounter++;$('#drop-overlay').classList.add('active');}});document.addEventListener('dragover',event=>{if(event.dataTransfer?.types?.includes('Files'))event.preventDefault();});document.addEventListener('dragleave',()=>{dragCounter=Math.max(0,dragCounter-1);if(!dragCounter)$('#drop-overlay').classList.remove('active');});document.addEventListener('drop',event=>{event.preventDefault();dragCounter=0;$('#drop-overlay').classList.remove('active');if(event.dataTransfer?.files.length)uploadFiles(event.dataTransfer.files);});
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.body.classList.remove('sidebar-hidden');$('#chat-search').focus();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='n'){event.preventDefault();newChat();}if(event.key==='Escape'&&document.getElementById('model-menu')){event.preventDefault();closeModelMenu(true);return;}if(event.key==='Escape'){document.querySelector('.context-menu')?.remove();if(state.busy)stopRun();}});
  $('#document-dialog').addEventListener('cancel',event=>{event.preventDefault();closeDocument();});
  $('#voice-dialog').addEventListener('cancel',event=>{if(state.voice){event.preventDefault();closeVoice();}});
  document.addEventListener('click',async event=>{const button=event.target.closest('button,[data-preview]');if(!event.target.closest('.context-menu')&&!event.target.closest('[data-chat-menu]'))document.querySelector('.context-menu')?.remove();if(!button)return;
    try{
      if(button.dataset.deleteModel){
        const model=button.dataset.deleteModel;
        let dialog=$('#delete-model-dialog');
        if(!dialog){dialog=document.createElement('dialog');dialog.id='delete-model-dialog';dialog.innerHTML='<div class="dialog-head"><h2>Удалить модель?</h2></div><div class="dialog-body"><p id="delete-model-description"></p><p class="form-help">Её можно скачать снова. Переписка и файлы сохранятся. Если модель выбрана для задачи, перед следующим запросом выберите другую или скачайте её заново.</p></div><div class="dialog-foot"><button class="button" data-close="delete-model-dialog">Отмена</button><button class="button danger" id="delete-model-confirm">Удалить</button></div>';document.body.append(dialog);}
        $('#delete-model-description').textContent=modelName(model);
        $('#delete-model-confirm').onclick=async()=>{const confirm=$('#delete-model-confirm');confirm.disabled=true;try{await api('/api/models/delete',{method:'POST',body:{model}});dialog.close();await refreshStatus();toast('Модель удалена');}catch(error){toast(error.message,true);}finally{confirm.disabled=false;}};
        dialog.showModal();return;
      }
      if(button.dataset.downloadModel)return await pullModels(button.dataset.downloadModel);
      if(button.dataset.mode){if(state.busy){toast('Режим можно сменить после завершения ответа.');return;}setMode(button.dataset.mode);return;}
      if(button.dataset.chat)return await selectChat(button.dataset.chat);
      if(button.dataset.chatMenu)return chatMenu(button.dataset.chatMenu,button);
      if(button.dataset.remove){state.pending=state.pending.filter(a=>a.id!==button.dataset.remove);renderPending();return;}
      if(button.dataset.preview)return await preview(button.dataset.preview);
      if(button.dataset.treePath){insertText('`'+button.dataset.treePath+'`');return;}
      if(button.dataset.close){$('#'+button.dataset.close).close();return;}
      if(button.hasAttribute('data-copy-tool-text'))return await copy(button.closest('.tool-file').querySelector('pre').textContent);
      if(button.hasAttribute('data-copy-code'))return await copy(button.closest('.code-block').querySelector('code').textContent);
      if(button.dataset.copyMessage!==undefined)return await copy(state.chat.messages[+button.dataset.copyMessage].content);
      if(button.dataset.saveMessage!==undefined)return download(state.chat.messages[+button.dataset.saveMessage].content,'message.md');
      if(button.dataset.editMessage!==undefined){$('#prompt').value=state.chat.messages[+button.dataset.editMessage].content;resizeInput();$('#prompt').focus();return;}
      if(button.dataset.installCompute){await installCompute(button.dataset.installCompute);return;}
      if(button.dataset.projectGit){await projectGit(button.dataset.projectGit);return;}
      if(button.dataset.projectCommand){insertText('Запусти проверку в папке '+JSON.stringify(button.dataset.projectDirectory)+': '+button.dataset.projectCommand);$('#projects-dialog').close();return;}
      if(button.dataset.downloadExecution){await downloadExecution(button.dataset.downloadExecution);return;}
      if(button.dataset.restoreChange){button.disabled=true;try{await restoreChange(button.dataset.restoreChange);}finally{button.disabled=false;}return;}
      if(button.dataset.approve||button.dataset.deny){const id=button.dataset.approve||button.dataset.deny;button.closest('.approval-actions').querySelectorAll('button').forEach(b=>b.disabled=true);await api('/api/approve/'+id,{method:'POST',body:{allow:!!button.dataset.approve}});return;}
      if(button.dataset.renameChat){const id=button.dataset.renameChat;const chat=state.chats.find(c=>c.id===id);document.querySelector('.context-menu')?.remove();editDialog('Название чата',chat.title,'Сохранить',async title=>{await api('/api/chats/'+id,{method:'PATCH',body:{title}});if(state.chat?.id===id){state.chat.title=title;$('#chat-title').textContent=title;}await refreshChats();});return;}
      if(button.dataset.deleteChat){const id=button.dataset.deleteChat;document.querySelector('.context-menu')?.remove();editDialog('Удалить чат?','История этого диалога будет удалена.','Удалить',async()=>{await api('/api/chats/'+id,{method:'DELETE'});if(state.chat?.id===id)newChat();await refreshChats();});return;}
      if(button.dataset.suggestion){const suggestion=button.dataset.suggestion;if(suggestion==='translate'){setMode('translate');$('#prompt').focus();}if(suggestion==='image'){$('#file-input').accept='image/*';$('#file-input').click();}if(suggestion==='audio')openVoice();if(suggestion==='agent'){setMode('agent');$('#prompt').value='Посмотри файлы в рабочей папке и расскажи, как устроен проект.';resizeInput();$('#prompt').focus();}return;}
      switch(button.dataset.action){case 'read-document':await readDocument();break;case 'next-document':$('#document-start').value=documentState.read?.next_page||1;await readDocument();break;case 'insert-document':if(documentState.read?.text){insertText(documentState.read.text);await closeDocument();}break;case 'translate-document':await translateDocument();break;case 'stop-document':await stopDocument();break;case 'close-document':await closeDocument();break;case 'attach-document-result':if(documentState.output){if(state.pending.length>=12)throw new Error('Максимум 12 вложений');if(!state.pending.some(a=>a.id===documentState.output.id))state.pending.push(documentState.output);renderPending();await closeDocument();}break;case 'install-browser':await installBrowserComponents();break;case 'assistant-config':await showAssistantConfig();break;case 'refresh-hardware':await loadCompute(true);break;case 'retry-compute':await retryCompute();break;case 'projects':await showProjects();break;case 'inspect-project':await inspectProject();break;case 'use-project':await useProject();break;case 'changes':await showChanges();break;case 'quick-help':toast('Выделите текст в другом приложении и нажмите '+(state.settings.quick_hotkey||'Control+Shift+T')+'. Для обычного копирования доступен переводчик: '+location.origin+'/quick.html');break;case 'new-chat':newChat();break;case 'sidebar':document.body.classList.toggle('sidebar-hidden');break;case 'files':await toggleFiles();break;case 'settings':await showSettings();break;case 'save-settings':await saveSettings();break;case 'export':exportChat();break;case 'attach':$('#file-input').accept='';$('#file-input').click();break;case 'paste':await pasteClipboard();break;case 'send':await send();break;case 'retry':await send(true);break;case 'swap':{const source=$('#source').value;$('#source').value=$('#target').value;$('#target').value=source;break;}case 'pull':await pullModels();break;case 'voice':openVoice();break;case 'record':await startRecord();break;case 'system-record':await systemRecord();break;case 'close-voice':await closeVoice();break;case 'use-voice':insertText($('#voice-result').value);$('#voice-dialog').close();break;}
    }catch(error){toast(error.message,true);}
  });
}
async function boot(){try{const bootstrap=await api('/api/bootstrap');state.token=bootstrap.token;state.settings=bootstrap.settings;state.catalog=bootstrap.catalog||[];state.mode=localStorage.getItem('gemma.mode')||'agent';if(!modes[state.mode])state.mode='agent';buildShell();updateWorkspace();await refreshChats();const last=localStorage.getItem('gemma.lastChat');if(last&&state.chats.some(c=>c.id===last))await selectChat(last);else renderMessages();$('#prompt').value=localStorage.getItem('gemma.draft')||'';resizeInput();await refreshStatus();setInterval(refreshStatus,15000);}catch(error){$('#app').innerHTML=`<div class="boot">Не удалось подключиться<span>${escapeHtml(error.message)}</span></div>`;}}
boot();
